INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'diverse', 'adj.', '/daɪˈvɜːs/', '不同的;多种多样的', 'San Francisco is a city with many diverse cultures.', '旧金山是一座拥有多元文化的城市。', 'Diverse Cultures', 1, 0, 'senior', 'wordlist', 'required3', 'U3', 'diverse cultures', '美音 /daɪˈvɜːrs/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'diversity', 'n.', '/daɪˈvɜːsəti/', '差异(性);多样性;多元化', 'The cultural diversity of the city makes it special.', '这座城市的文化多样性使它与众不同。', 'Diverse Cultures', 2, 0, 'senior', 'wordlist', 'required3', 'U3', 'cultural diversity', '美音 /daɪˈvɜːrsəti/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'ethnic', 'adj.', '/ˈeθnɪk/', '民族的;种族的;有民族特色的', 'Guizhou is home to many ethnic minority groups.', '贵州是许多少数民族群体的家园。', 'Diverse Cultures', 3, 0, 'senior', 'wordlist', 'required3', 'U3', 'ethnic minority', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'minority', 'n.', '/maɪˈnɒrəti/', '少数民族;少数派;少数人', 'We visited several ethnic minority villages in Guizhou.', '我们参观了贵州的几个少数民族村寨。', 'Diverse Cultures', 4, 0, 'senior', 'wordlist', 'required3', 'U3', 'ethnic minority villages', '美音 /maɪˈnɔːrəti/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'immigrant', 'n.', '/ˈɪmɪɡrənt/', '(外来)移民;外侨', 'Many Chinese immigrants settled in San Francisco''s Chinatown.', '许多华人移民在旧金山唐人街定居下来。', 'Diverse Cultures', 5, 0, 'senior', 'wordlist', 'required3', 'U3', 'Chinese immigrants', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'settle', 'v.', '/ˈsetl/', '定居;解决(分歧);安排好', 'Immigrants from many countries settled in this district.', '来自许多国家的移民在这个区定居。', 'Diverse Cultures', 6, 0, 'senior', 'wordlist', 'required3', 'U3', 'settle in the area', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'earn', 'v.', '/ɜːn/', '挣得;赚得;赢得;博得', 'Some immigrants opened shops to earn a living.', '一些移民开店谋生。', 'Diverse Cultures', 7, 0, 'senior', 'wordlist', 'required3', 'U3', 'earn a living', '美音 /ɜːrn/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'seek', 'v.', '/siːk/', '寻找;寻求', 'Thousands of people came here to seek their fortune.', '成千上万的人来到这里寻找致富之路。', 'Diverse Cultures', 8, 0, 'senior', 'wordlist', 'required3', 'U3', 'seek one''s fortune', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'fortune', 'n.', '/ˈfɔːtʃuːn/', '运气;机会;大笔的钱', 'During the gold rush, people hoped to make a fortune.', '淘金热期间,人们都希望发大财。', 'Diverse Cultures', 9, 0, 'senior', 'wordlist', 'required3', 'U3', 'seek one''s fortune', '美音 /ˈfɔːrtʃən/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'escape', 'v./n.', '/ɪˈskeɪp/', '逃走;逃脱;避开;逃跑', 'Many people visit Yunnan to escape the cold winter.', '许多人去云南是为了躲避寒冷的冬天。', 'Diverse Cultures', 10, 0, 'senior', 'wordlist', 'required3', 'U3', 'escape the cold winter', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'claim', 'v./n.', '/kleɪm/', '夺取(生命);宣称;断言', 'The earthquake claimed thousands of lives in 1906.', '1906 年那场地震夺去了数千人的生命。', 'Diverse Cultures', 11, 0, 'senior', 'wordlist', 'required3', 'U3', 'claim lives', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'occur', 'v.', '/əˈkɜː(r)/', '发生;出现', 'A terrible earthquake occurred in San Francisco in 1906.', '1906 年旧金山发生了一场可怕的地震。', 'Diverse Cultures', 12, 0, 'senior', 'wordlist', 'required3', 'U3', 'an earthquake occurred', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'historical', 'adj.', '/hɪˈstɒrɪkl/', '(有关)历史的', 'The museum showed the historical changes in California.', '这座博物馆展示了加利福尼亚的历史变迁。', 'Diverse Cultures', 13, 0, 'senior', 'wordlist', 'required3', 'U3', 'historical changes', '美音 /hɪˈstɔːrɪkl/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'downtown', 'adv./adj.', '/ˌdaʊnˈtaʊn/', '在市中心;往市中心;市中心的', 'My hotel is near downtown, in an old part of the city.', '我的旅馆靠近市中心,在城里一个古老的区域。', 'Diverse Cultures', 14, 0, 'senior', 'wordlist', 'required3', 'U3', 'near downtown', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'graffiti', 'n.', '/ɡrəˈfiːti/', '涂鸦;胡写乱画', 'The street art here is influenced by graffiti art.', '这里的街头艺术受到了涂鸦艺术的影响。', 'Diverse Cultures', 15, 0, 'senior', 'wordlist', 'required3', 'U3', 'graffiti art', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'comic', 'adj./n.', '/ˈkɒmɪk/', '滑稽的;漫画杂志;喜剧演员', 'The Mission School style mixes graffiti and comic art.', '“密遜画派”风格融合了涂鸦与漫画艺术。', 'Diverse Cultures', 16, 0, 'senior', 'wordlist', 'required3', 'U3', 'comic art', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'select', 'v.', '/sɪˈlekt/', '选择;挑选;选拔', 'I selected a Cantonese restaurant in Chinatown for dinner.', '我在唐人街挑了一家粤菜馆吃晚饭。', 'Diverse Cultures', 17, 0, 'senior', 'wordlist', 'required3', 'U3', 'select a restaurant', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'series', 'n.', '/ˈsɪəriːz/', '一系列;一连串;接连', 'A series of fires followed the great earthquake.', '大地震之后接连发生了一系列火灾。', 'Diverse Cultures', 18, 0, 'senior', 'wordlist', 'required3', 'U3', 'a series of fires', '美音 /ˈsɪriːz/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'percentage', 'n.', '/pəˈsentɪdʒ/', '百分率;百分比', 'A large percentage of the city was destroyed by the fires.', '城市的很大一部分被大火摧毁了。', 'Diverse Cultures', 19, 0, 'senior', 'wordlist', 'required3', 'U3', 'a large percentage', '美音 /pərˈsentɪdʒ/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'financial', 'adj.', '/faɪˈnænʃl/', '财政的;财务的;金融的', 'He tried hard to solve his financial problems.', '他努力解决自己的经济问题。', 'Diverse Cultures', 20, 0, 'senior', 'wordlist', 'required3', 'U3', 'financial problems', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'construction', 'n.', '/kənˈstrʌkʃn/', '建筑;建造;结构', 'Chinese immigrants worked during the railroad construction.', '华人移民在铁路修建期间工作。', 'Diverse Cultures', 21, 0, 'senior', 'wordlist', 'required3', 'U3', 'railroad construction', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'contain', 'v.', '/kənˈteɪn/', '包含;含有;容纳', 'The rebuilt area was made to contain lots of Chinese architecture.', '重建的区域被设计成包含大量中式建筑。', 'Diverse Cultures', 22, 0, 'senior', 'wordlist', 'required3', 'U3', 'contain Chinese architecture', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'material', 'n./adj.', '/məˈtɪəriəl/', '材料;布料;物质的', 'The Dragon Gate was built using materials donated from China.', '龙门是用从中国捐赠的材料建造的。', 'Diverse Cultures', 23, 0, 'senior', 'wordlist', 'required3', 'U3', 'building materials', '美音 /məˈtɪriəl/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'souvenir', 'n.', '/ˌsuːvəˈnɪə(r)/', '纪念物;纪念品', 'Justin wanted to buy some hand-made accessories as souvenirs.', '贾斯汀想买些手工饰品作纪念品。', 'Diverse Cultures', 24, 0, 'senior', 'wordlist', 'required3', 'U3', 'buy souvenirs', '美音 /ˌsuːvəˈnɪr/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'clothing', 'n.', '/ˈkləʊðɪŋ/', '衣服;服装', 'The stores offer souvenirs, goods, and clothing.', '这些商店出售纪念品、商品和服装。', 'Diverse Cultures', 25, 0, 'senior', 'wordlist', 'required3', 'U3', 'traditional clothing', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'herbal', 'adj.', '/ˈhɜːbl/', '药草的;香草的', 'All kinds of Chinese herbal medicine can be found here.', '在这里能找到各种中草药。', 'Diverse Cultures', 26, 0, 'senior', 'wordlist', 'required3', 'U3', 'herbal medicine', '美音 /ˈɜːrbl/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'mild', 'adj.', '/maɪld/', '温和的;和善的;轻微的', 'The climate is mild all year round in Chinatown.', '唐人街全年气候温和。', 'Diverse Cultures', 27, 0, 'senior', 'wordlist', 'required3', 'U3', 'a mild climate', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'climate', 'n.', '/ˈklaɪmət/', '气候', 'A mild climate makes it a good time to visit all year.', '温和的气候使这里全年都适合游览。', 'Diverse Cultures', 28, 0, 'senior', 'wordlist', 'required3', 'U3', 'a mild climate', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'suit', 'v./n.', '/suːt/', '适合;满足……需要;西服;套装', 'There is Chinese food here to suit everyone''s taste.', '这里有适合各种口味的中餐。', 'Diverse Cultures', 29, 0, 'senior', 'wordlist', 'required3', 'U3', 'suit everyone''s taste', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'spicy', 'adj.', '/ˈspaɪsi/', '加有香料的;辛辣的', 'Gumbo is a spicy stew invented in New Orleans.', '秋葵汤是一种发明于新奥尔良的辛辣炖菜。', 'Diverse Cultures', 30, 0, 'senior', 'wordlist', 'required3', 'U3', 'a spicy stew', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'mushroom', 'n.', '/ˈmʌʃrʊm/', '蘑菇;蕈', 'Some wild mushrooms are poisonous and some are not.', '有些野生蘑菇有毒,有些则没有。', 'Diverse Cultures', 31, 0, 'senior', 'wordlist', 'required3', 'U3', 'wild mushrooms', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'poisonous', 'adj.', '/ˈpɔɪzənəs/', '有毒的;引起中毒的', 'You should never eat a poisonous mushroom.', '你绝不能吃有毒的蘑菇。', 'Diverse Cultures', 32, 0, 'senior', 'wordlist', 'required3', 'U3', 'poisonous mushrooms', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'poison', 'n./v.', '/ˈpɔɪzn/', '毒物;毒药;毒死;毒害', 'Some plants contain a poison that can harm people.', '有些植物含有能伤害人的毒素。', 'Diverse Cultures', 33, 0, 'senior', 'wordlist', 'required3', 'U3', 'a deadly poison', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'fold', 'v.', '/fəʊld/', '折叠;包;裹', 'I really like that paper folding book, and so does my son.', '我很喜欢那本折纸书,我儿子也喜欢。', 'Diverse Cultures', 34, 0, 'senior', 'wordlist', 'required3', 'U3', 'paper folding', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'item', 'n.', '/ˈaɪtəm/', '项目;一件商品;一条(新闻)', 'Each item on the Chinatown menu tells a small story.', '唐人街菜单上的每道菜都讲述着一个小故事。', 'Diverse Cultures', 35, 0, 'senior', 'wordlist', 'required3', 'U3', 'an item on the menu', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'poetry', 'n.', '/ˈpəʊətri/', '诗歌;诗集;诗作', 'The instrument is mentioned in the oldest collection of Chinese poetry.', '这种乐器在最古老的中国诗歌总集中被提到过。', 'Diverse Cultures', 36, 0, 'senior', 'wordlist', 'required3', 'U3', 'a collection of poetry', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'collection', 'n.', '/kəˈlekʃn/', '收藏品;收集物;作品集', 'The museum has a large collection of historical items.', '这座博物馆收藏了大量历史物品。', 'Diverse Cultures', 37, 0, 'senior', 'wordlist', 'required3', 'U3', 'a collection of poetry', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'journal', 'n.', '/ˈdʒɜːnl/', '日志;日记;报纸;刊物', 'Li Lan wrote a travel journal about her trip to San Francisco.', '李兰写了一篇关于旧金山之行的旅行日志。', 'Diverse Cultures', 38, 0, 'senior', 'wordlist', 'required3', 'U3', 'a travel journal', '美音 /ˈdʒɜːrnl/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'definitely', 'adv.', '/ˈdefɪnətli/', '肯定;确实', 'The Huangguoshu Waterfall is definitely worth visiting.', '黄果树瀑布确实值得一去。', 'Diverse Cultures', 39, 0, 'senior', 'wordlist', 'required3', 'U3', 'definitely worth visiting', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'neat', 'adj.', '/niːt/', '整洁的;整齐的;极好的', 'He arranged all the souvenirs in a neat row.', '他把所有纪念品摆成整齐的一排。', 'Diverse Cultures', 40, 0, 'senior', 'wordlist', 'required3', 'U3', 'a neat row', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'diagram', 'n.', '/ˈdaɪəɡræm/', '简图;图解;示意图', 'You can draw a diagram to organise the information in the journal.', '你可以画一张示意图来梳理日志中的信息。', 'Diverse Cultures', 41, 0, 'senior', 'wordlist', 'required3', 'U3', 'draw a diagram', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'super', 'adj.', '/ˈsuːpə(r)/', '顶好的;超级的', 'Justin was super excited about his trip to Guizhou.', '贾斯汀对去贵州的旅行感到超级兴奋。', 'Diverse Cultures', 42, 0, 'senior', 'wordlist', 'required3', 'U3', 'super excited', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'jeans', 'n.', '/dʒiːnz/', '牛仔裤', 'A dress might look better than jeans and boots tonight.', '今晚连衣裙也许比牛仔裤和靴子更好看。', 'Diverse Cultures', 43, 0, 'senior', 'wordlist', 'required3', 'U3', 'a pair of jeans', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'chip', 'n.', '/tʃɪp/', '炸薯片;炸土豆条;芯片;碎片', 'Nachos are corn chips covered in cheese.', '墨西哥玉米片是裹上奶酪的玉米片。', 'Diverse Cultures', 44, 0, 'senior', 'wordlist', 'required3', 'U3', 'corn chips', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'cheese', 'n.', '/tʃiːz/', '干酪;奶酪', 'The corn chips were covered in warm cheese.', '玉米片裹上了温热的奶酪。', 'Diverse Cultures', 45, 0, 'senior', 'wordlist', 'required3', 'U3', 'covered in cheese', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'china', 'n.', '/ˈtʃaɪnə/', '瓷;瓷器', 'The restaurant served its food on beautiful china plates.', '这家餐馆用精美的瓷盘上菜。', 'Diverse Cultures', 46, 0, 'senior', 'wordlist', 'required3', 'U3', 'china plates', NULL);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('r3u3.01', '①不定式的省略(保留 to,省略后面的动词原形)', 'A2', 10, '必修三 U3 — 当不定式所表达的动作在上文已出现时,常只保留 to,省略其后的动词(及宾语):—Will you join us? —I''d love to. / You can go if you want to. / I didn''t mean to. 若动词为 be/完成体 have,则保留 to be / to have。', 1, 'required3', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('r3u3.02', '②状语从句的省略(连词 + V-ing / V-ed / adj,省略“主语 + be”)', 'A2', 10, '必修三 U3 — 当状语从句的主语与主句主语一致(或为 it)且谓语含 be 时,可省略“主语 + be”,只留连词 + 现在分词/过去分词/形容词/介词短语:When (you are) in Rome, do as the Romans do. / If (it is) necessary, call me. / Though (he was) tired, he kept working.', 2, 'required3', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('r3u3.03', '③对话/并列句中重复成分的省略(省主语、助动词、重复谓语等)', 'A2', 10, '必修三 U3 — 为避免重复,对话答语或并列句中常省去与上文相同的成分,只保留新信息或助动词/be/情态动词:—Where are you going? —(I''m going) To the library. / He can swim, and so can I. / She likes tea, but I don''t (like tea).', 3, 'required3', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.01'), '—Will you come to the ethnic festival with us? —I''d love ____.', 'to', 'to come it', 'come', 'to coming', 'A', '上文已有 come,不定式只保留 to,省略后面的动词。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.01'), 'You can visit Chinatown today if you really want ____.', 'to do it', 'to', 'want', 'to wanting', 'B', 'want 后接不定式,动作上文已提,只保留 to。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.01'), '—I''m sorry I stepped on your foot. —Don''t worry, you didn''t mean ____.', 'to it', 'mean', 'to', 'to meaning', 'C', 'mean to do,动作已知,只留 to。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.01'), 'She didn''t buy the souvenir, though she had hoped ____.', 'buy', 'to buying', 'to it', 'to', 'D', 'hope to do,buy 已出现,保留 to 省略动词。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.01'), '—Why didn''t you taste the gumbo? —I wanted ____, but it was all gone.', 'to', 'taste', 'to tasting', 'to taste it it', 'A', 'want to do,taste 上文已现,只留 to。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.01'), 'He doesn''t practise tai chi every day, but he used ____.', 'use', 'to', 'to doing', 'to it', 'B', 'used to do 表过去习惯,动词省略只保留 to。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.01'), '—Could you show me the Dragon Gate? —I''d be glad ____.', 'show', 'to showing', 'to', 'to show it it', 'C', 'be glad to do,动作已知,保留 to。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.01'), 'I haven''t tried the spicy stew yet, but I''m going ____ tonight.', 'try', 'to trying', 'to it', 'to', 'D', 'be going to do,try 已提,留 to 省略动词。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.01'), '—Have you booked the trip to Guizhou? —Not yet, but I plan ____ tomorrow.', 'to', 'book', 'to booking', 'to it', 'A', 'plan to do,book 上文已现,保留 to。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.01'), 'You needn''t taste every dish unless you''d like ____.', 'taste', 'to', 'to tasting', 'like', 'B', 'would like to do,taste 已知,只留 to。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.01'), '—Will Justin join the village tour? —He''d really like ____.', 'join', 'to joining', 'to', 'to join it it', 'C', 'would like to do,join 已现,保留 to。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.01'), 'I didn''t write the travel journal myself, though I ought ____.', 'write', 'to writing', 'to it', 'to', 'D', 'ought to do,write 已知,保留 to。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.01'), '—Did you climb to the waterfall cave? —I tried ____, but it was too steep.', 'to', 'climb', 'to climbing', 'climb it', 'A', 'try to do,climb 上文已现,只留 to。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.01'), '—You should taste the fortune cookie. —I''m just about ____.', 'taste', 'to', 'to tasting', 'to it', 'B', 'be about to do,taste 已知,保留 to 省略动词。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.01'), 'She wanted to buy the herbal medicine but wasn''t allowed ____.', 'buy', 'to buying', 'to', 'to buy it it', 'C', 'be allowed to do,buy 已现,只留 to。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.01'), '—Will you record his story for the journal? —Sure, I''m happy ____.', 'record', 'to recording', 'to it', 'to', 'D', 'be happy to do,record 已知,保留 to。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.01'), 'He hasn''t moved to the Mission District yet, but he hopes ____ soon.', 'to', 'move', 'to moving', 'to it', 'A', 'hope to do,move 上文已现,留 to。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.01'), '—Are you going to learn the lusheng? —Yes, I really intend ____.', 'learn', 'to', 'to learning', 'to learn it it', 'B', 'intend to do,learn 已现,保留 to。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.01'), 'I didn''t explore the whole museum, although I''d planned ____.', 'explore', 'to exploring', 'to', 'to it', 'C', 'plan to do,explore 已知,只留 to。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.01'), '—Could you carry these souvenirs for me? —Of course, I''d be glad ____.', 'carry', 'to carrying', 'carry them', 'to', 'D', 'be glad to do,carry 已现,保留 to。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.02'), 'When ____ in Rome, do as the Romans do.', 'in', 'you are be', 'being are', 'are in', 'A', '状语从句省略“主语 + be”,只留连词加介词短语:When (you are) in Rome。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.02'), 'If ____ necessary, please call your guide for help.', 'it necessary is', 'necessary', 'necessarily', 'being necessary it', 'B', 'If (it is) necessary,省略“it is”,只留形容词 necessary。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.02'), 'Though ____ tired, the travellers kept walking through Chinatown.', 'they tired', 'tiring them', 'tired', 'being tired they', 'C', 'Though (they were) tired,省略“主语 + be”,留过去分词 tired。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.02'), 'While ____ in Guizhou, Justin met many friendly local people.', 'he travelling', 'travelled he', 'he travel', 'travelling', 'D', 'While (he was) travelling,省略“he was”,留现在分词 travelling。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.02'), 'When ____ from the hill, the Golden Gate Bridge looks amazing.', 'seen', 'it seen', 'seeing it', 'see it', 'A', 'When (it is) seen,被动省略留过去分词 seen。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.02'), 'Unless ____ to do so, visitors should not touch the old china plates.', 'they asking', 'asked', 'ask them', 'asking they', 'B', 'Unless (they are) asked,被动省略留过去分词 asked。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.02'), 'Once ____ with cheese, the corn chips become tasty nachos.', 'they covering', 'covering them', 'covered', 'cover them', 'C', 'Once (they are) covered,被动省略留过去分词 covered。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.02'), 'If ____ for advice, ask a local about the best ethnic restaurants.', 'it possibly', 'being possible it', 'it possible is', 'possible', 'D', 'If (it is) possible,省略“it is”,留形容词 possible。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.02'), 'Although ____ as a poor area, the Mission District is now a centre for art.', 'known', 'it knowing', 'knowing it', 'know it', 'A', 'Although (it is) known,被动省略留过去分词 known。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.02'), 'When ____ a foreign city, try to learn a little of its local culture.', 'you visiting', 'visiting', 'visit you', 'you visit it', 'B', 'When (you are) visiting,省略“you are”,留现在分词 visiting。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.02'), 'Whenever ____ in doubt about a word, just ask politely.', 'you in are', 'being in you', 'in', 'are in you', 'C', 'Whenever (you are) in doubt,省略“you are”,留介词短语。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.02'), 'While ____ at street art, Li Lan spent a few happy hours in the district.', 'she looking', 'look she', 'she look', 'looking', 'D', 'While (she was) looking,省略“she was”,留现在分词 looking。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.02'), 'If ____, the hand-made silver accessories make wonderful souvenirs.', 'wanted', 'they wanting', 'wanting them', 'want them', 'A', 'If (they are) wanted,被动省略留过去分词 wanted。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.02'), 'Though ____ small, the village shows a rich ethnic minority culture.', 'it small', 'small', 'being small it', 'small it is', 'B', 'Though (it is) small,省略“it is”,留形容词 small。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.02'), 'When ____ for the first time, the lusheng music sounds quite unusual.', 'it hearing', 'hearing it', 'heard', 'hear it', 'C', 'When (it is) heard,被动省略留过去分词 heard。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.02'), 'While ____ his trip, Justin took many photos of the waterfall.', 'he enjoying', 'enjoy he', 'he enjoy', 'enjoying', 'D', 'While (he was) enjoying,省略“he was”,留现在分词 enjoying。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.02'), 'If ____ carefully, the diverse culture of China is easy to appreciate.', 'studied', 'it studying', 'studying it', 'study it', 'A', 'If (it is) studied,被动省略留过去分词 studied。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.02'), 'Although ____ from China, the gate''s materials were used to build it locally.', 'they donating', 'donated', 'donating them', 'donate them', 'B', 'Although (they were) donated,被动省略留过去分词 donated。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.02'), 'When ____ about Chinatown, most visitors first mention its food.', 'they asking', 'asking them', 'asked', 'ask them', 'C', 'When (they are) asked,被动省略留过去分词 asked。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.02'), 'While ____ at the potluck dinner, we shared dishes from many cultures.', 'we eating', 'eat we', 'we eat', 'eating', 'D', 'While (we were) eating,省略“we were”,留现在分词 eating。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.03'), '—Where are you heading this evening? —____ Chinatown.', 'To', 'I', 'Going', 'Am', 'A', '答语省略“I''m heading to”,只留新信息,介词 To 起头。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.03'), 'Justin loves the ethnic villages, and ____ does Linlin.', 'as', 'so', 'also', 'either', 'B', '“so + 助动词 + 主语”表示后者也如此:so does Linlin。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.03'), '—I just love these nachos! —____ do I.', 'Either', 'Also', 'So', 'Neither', 'C', '肯定附和用“So do I”,省去重复的谓语 love them。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.03'), 'She has visited Chinatown, but I ____.', 'don''t', 'didn''t', 'amn''t', 'haven''t', 'D', '省略重复谓语,只留助动词:but I haven''t (visited it)。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.03'), '—Have you ever heard of Journey to the West? —Yes, I ____.', 'have', 'do', 'did', 'am', 'A', '用助动词代替整个谓语:Yes, I have (heard of it)。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.03'), '—Who wants to try the fortune cookie? —____ do!', 'Me am', 'I', 'Mine', 'I''m', 'B', '答语省略重复谓语,只留主语加助动词:I do!', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.03'), '—What a real mix of cultures here! —____ it is!', 'As', 'Such', 'So', 'Very', 'C', '附和上句用“So it is”,省略 a real mix of cultures。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.03'), 'Linlin can speak the local dialect, and ____ can her brother.', 'as', 'also', 'neither', 'so', 'D', '“so + can + 主语”表后者也能:so can her brother。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.03'), '—Did you enjoy the waterfall? —Yes, I ____, very much.', 'did', 'do', 'have', 'was', 'A', '用助动词 did 代替 enjoyed it,省略重复谓语。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.03'), 'He didn''t taste the spicy stew, and ____ did I.', 'so', 'neither', 'also', 'too', 'B', '否定附和用“neither + did + 主语”:neither did I。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.03'), '—Are you going to the jazz bar tonight? —Yes, I ____.', 'do', 'will go to', 'am', 'go', 'C', '用 be 动词代替整个谓语:Yes, I am (going)。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.03'), '—Would you recommend the museum? —I certainly ____.', 'do', 'am', 'did', 'would', 'D', '用情态动词 would 代替 recommend it,省略重复谓语。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.03'), 'Some wild mushrooms are poisonous, and some ____ not.', 'are', 'do', 'have', 'were', 'A', '并列句省略 poisonous,只留 be 动词:some are not。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.03'), '—Can you wait a moment? —____ wait.', 'Don''t can', 'Can''t', 'No can', 'Not can', 'B', '口语省略主语 I,只留助动词:Can''t wait!(= I can''t wait)。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.03'), 'She likes Cantonese food, but her friend ____.', 'don''t', 'isn''t', 'doesn''t', 'didn''t', 'C', '省略重复谓语 like it,只留助动词:but her friend doesn''t。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.03'), '—Is the climate mild here? —Yes, it ____.', 'does', 'has', 'did', 'is', 'D', '用 be 动词代替整个谓语:Yes, it is (mild)。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.03'), 'I have been to Yunnan, but my sister ____.', 'hasn''t', 'doesn''t', 'isn''t', 'didn''t', 'A', '完成时省略重复谓语,只留助动词:but my sister hasn''t。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.03'), '—So it''s the food of many cultures, all in one dish? —____.', 'Exact', 'Exactly', 'So exact', 'Very exact', 'B', '答语用一个词 Exactly 代替整句,省略重复内容。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.03'), '—Will the villagers perform a dance? —I hope ____.', 'it', 'that', 'so', 'this', 'C', 'hope so 用 so 代替前面整句,省略重复内容。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U3' AND code='r3u3.03'), 'Justin took lots of photos, and ____ did his friends.', 'as', 'also', 'neither', 'so', 'D', '“so + did + 主语”表后者也如此:so did his friends。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'A City of Many Cultures', 'San Francisco is one of the most exciting cities in the world, partly because so many different cultures meet there. The city was able to rebuild itself after the terrible earthquake that occurred in 1906, and today it is full of beautiful old buildings sitting on top of big hills. From these hills, visitors can enjoy great views of the ocean and the famous Golden Gate Bridge. What makes the city special, however, is its people. Over the years, immigrants from Mexico, China, and many other countries have settled here, each group bringing its own food, music, and traditions. In one street you might smell Mexican cooking, while in the next you hear Cantonese being spoken. Because of this mix, the city has become a true home of cultural diversity. People who grow up here learn from a young age that there are many different ways of living, eating, and seeing the world.', '说明·旧金山的多元文化', 153, '[{"q":"Why is San Francisco described as exciting?","answer":"A","options":["Because cultures from many places come together there.","Because it has no tall hills.","Because no one ever moved there.","Because it has only one kind of food."],"explanation":"首段 ''so many different cultures meet there'' 的转述。"},{"q":"What can visitors do from the city''s hills?","answer":"B","options":["Swim in the river.","See the ocean and the Golden Gate Bridge.","Watch a football match.","Visit a poison museum."],"explanation":"原文 ''great views of the ocean and the famous Golden Gate Bridge'' 的转述。"},{"q":"According to the text, what makes the city truly special?","answer":"A","options":["Its mix of people from many cultures.","Its tall new offices.","Its cheap hotels.","Its cold weather."],"explanation":"末段强调 ''its people'' 与 ''cultural diversity'',为概括转述。"}]'::jsonb, '[{"word":"diversity","cn":"多样性"},{"word":"immigrant","cn":"移民"},{"word":"occur","cn":"发生"}]'::jsonb, 2, 'required3', 'U3');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'Coming to a New Home', 'In 1848, gold was discovered near San Francisco, and the news spread quickly across the world. Soon over three hundred thousand people came from many countries, all hoping to seek their fortune. Among them were many Chinese, who arrived during this busy period. Life was not easy for these newcomers. To earn a living, some opened small shops and restaurants in the area that later became Chinatown. Others found jobs on farms, joined the gold rush, or helped to build the great railway that joined California to the eastern part of the country. The work was hard and the pay was low, but they kept going, year after year. When these immigrants left their home countries, they carried a little piece of home in their hearts. In time, they built a new home in a faraway land, and their children grew up proud of two cultures at once. Their story is part of how the country was built by people from all over the world.', '记叙·移民与淘金热', 165, '[{"q":"What brought so many people to San Francisco in 1848?","answer":"B","options":["A new school.","The discovery of gold nearby.","A music festival.","A warm climate."],"explanation":"原文 ''gold was discovered… all hoping to seek their fortune'' 的转述。"},{"q":"How did some Chinese immigrants earn a living?","answer":"C","options":["By leaving the country at once.","By refusing to work.","By opening shops and restaurants.","By selling poison."],"explanation":"原文 ''opened small shops and restaurants'' 的转述。"},{"q":"What does the writer say the immigrants finally did?","answer":"D","options":["They forgot their old culture completely.","They returned home with the gold.","They stopped the railway from being built.","They created a fresh home in a distant land."],"explanation":"末段 ''built a new home in a faraway land'' 的转述。"}]'::jsonb, '[{"word":"seek","cn":"寻求"},{"word":"fortune","cn":"运气;财富"},{"word":"earn","cn":"挣得"}]'::jsonb, 2, 'required3', 'U3');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'Street Art in the Mission District', 'The Mission District is one of the oldest parts of San Francisco, and it has changed a great deal over the years. Many of the people living there came from Mexico or Central America. Long ago it was a poor area of town, but today it is a lively centre for art, music, and food. One of the most interesting things to see there is the street art. An art movement known as the Mission School began in this very district. It is influenced by both graffiti art and comic art, and its bright colours seem to jump off the walls. A visitor can walk around for hours, looking at painting after painting that tells a story about the people who live nearby. Afterwards, the same visitor might buy noodles from a food truck that mixes Mexican and Chinese cooking. In a single afternoon, you can see how different cultures meet, mix, and make something new and exciting. That is the real spirit of the district.', '说明·密遜区的街头艺术', 166, '[{"q":"What was the Mission District like long ago?","answer":"A","options":["A poor, run-down part of the city.","A rich shopping street.","An empty desert.","A famous museum."],"explanation":"原文 ''it was a poor area of town'' 的转述。"},{"q":"What influenced the Mission School art movement?","answer":"B","options":["Old Chinese poetry only.","Both street graffiti and the style of comics.","Photographs of the bridge.","Maps of California."],"explanation":"原文 ''influenced by both graffiti art and comic art'' 的转述。"},{"q":"What does the writer say you can learn there in one afternoon?","answer":"C","options":["How to drive a food truck.","How to paint comics.","How different cultures meet and create something new.","How to escape the cold winter."],"explanation":"末段 ''cultures meet, mix, and make something new'' 的转述。"}]'::jsonb, '[{"word":"graffiti","cn":"涂鸦"},{"word":"comic","cn":"漫画"},{"word":"downtown","cn":"市中心"}]'::jsonb, 2, 'required3', 'U3');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'Villages in Guizhou', 'Guizhou Province is famous for its cultural diversity, and it is home to many ethnic minority groups. When Justin travelled there, he was amazed by how different it felt from the big cities he knew. In one village, he watched local people play an old instrument called the lusheng. He was told that this instrument has a history of more than a thousand years, and it is even mentioned in the oldest collection of Chinese poetry. Justin also wanted to buy some hand-made silver accessories as souvenirs. A friendly villager explained that the price would depend on the percentage of real silver inside each piece. Later, the new friends planned to visit a pretty village built beside a clear river, where they hoped to see traditional dances and beautiful old houses. By the end of his trip, Justin understood that Chinese culture was far more diverse than he had ever imagined. He returned home with photos, gifts, and many new stories to share.', '记叙·贵州的民族村寨', 163, '[{"q":"What is Guizhou Province famous for?","answer":"D","options":["Its tall office buildings.","Its cold sea.","Its lack of villages.","Its cultural diversity and ethnic groups."],"explanation":"原文 ''famous for its cultural diversity… many ethnic minority groups'' 的转述。"},{"q":"What decided the price of the silver accessories?","answer":"A","options":["How much real silver each piece held.","The colour of the box.","The day of the week.","How heavy the buyer was."],"explanation":"原文 ''the price would depend on the percentage of real silver'' 的转述。"},{"q":"What did Justin understand by the end of his trip?","answer":"B","options":["That villages are all the same.","That China holds much greater cultural variety than he expected.","That he disliked travelling.","That the lusheng was easy to play."],"explanation":"末段 ''far more diverse than he had ever imagined'' 的转述。"}]'::jsonb, '[{"word":"minority","cn":"少数民族"},{"word":"souvenir","cn":"纪念品"},{"word":"percentage","cn":"百分比"}]'::jsonb, 2, 'required3', 'U3');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'Food from Everywhere', 'Some people think that America has no food of its own, but this is not really true. American cooking often takes ideas from many different cultures and mixes them to make something completely new. The hamburger, for example, brings together cooking ideas from more than one country. Nachos are simply corn chips covered in warm cheese; they were first made by a clever cook for a group of hungry visitors. Inside a fortune cookie you will find a small piece of paper with a lucky message on it, though such cookies are far more common in America than in China itself. Gumbo is a spicy stew that was invented in New Orleans long ago. It mixes cooking styles from several places, all in a single pot. What these foods share is the spirit of mixing. Just like the people of the country, American food is the result of many cultures meeting and sharing. Each dish tells a small story about the people who first made it.', '说明·美式融合食物', 166, '[{"q":"What does the writer say about American cooking?","answer":"C","options":["It never changes at all.","It comes from only one country.","It mixes ideas from many cultures to make new dishes.","It is always poisonous."],"explanation":"原文 ''takes ideas from many different cultures and mixes them'' 的转述。"},{"q":"What will you find inside a fortune cookie?","answer":"D","options":["A piece of cheese.","A silver coin.","A spicy stew.","A tiny slip printed with a lucky saying."],"explanation":"原文 ''a small piece of paper with a lucky message'' 的转述。"},{"q":"What do these different foods have in common?","answer":"A","options":["They all share the spirit of mixing cultures.","They are all sweet.","They were all made in China.","They are all very expensive."],"explanation":"末段 ''the spirit of mixing… many cultures meeting and sharing'' 的转述。"}]'::jsonb, '[{"word":"spicy","cn":"辛辣的"},{"word":"cheese","cn":"奶酪"},{"word":"chip","cn":"薯片;玉米片"}]'::jsonb, 2, 'required3', 'U3');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'The World''s Biggest Melting Pot', 'Queens is a neighbourhood in the city of New York, and many people say it is one of the most diverse places in the whole world. Almost half of the people living there were born in another country. Because so many cultures share the same streets, Queens is often called a melting pot, a place where people of different backgrounds live together side by side. Walk down a single road and you may hear dozens of different languages being spoken. One study even tried to measure diversity by working out how likely it was that two people chosen at random would come from different backgrounds. In Queens, the answer was very high indeed. Some people worry that life there might be hard for a newcomer, but many residents say the opposite is true: living among so many cultures makes them feel at home and helps them understand the wider world. For them, the rich mix of people is not a problem but a gift to be treasured.', '说明·纽约皇后区·大熔炉', 167, '[{"q":"Why is Queens called a melting pot?","answer":"B","options":["Because it is very hot there.","Because people of many backgrounds live together there.","Because no one lives there.","Because it has only one language."],"explanation":"原文 ''people of different backgrounds live together side by side'' 的转述。"},{"q":"What did one study try to measure?","answer":"C","options":["The number of cars in the city.","The price of houses.","The chance that two random people came from different backgrounds.","The weather over a year."],"explanation":"原文 ''measure diversity by working out how likely…'' 的转述。"},{"q":"How do many residents feel about the mix of cultures?","answer":"D","options":["They find it boring.","They wish everyone were the same.","They want to leave at once.","They view it as a precious blessing worth cherishing."],"explanation":"末段 ''not a problem but a gift to be treasured'' 的转述。"}]'::jsonb, '[{"word":"diverse","cn":"多种多样的"},{"word":"settle","cn":"定居"},{"word":"percentage","cn":"百分比"}]'::jsonb, 2, 'required3', 'U3');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required3', 'U3', 'Li Lan''s First Day Back', 'Today was my first day back in the city after a long camping (1)____. I have to admit that it definitely feels good to be here again. My hotel is near (2)____, in one of the oldest parts of town. Many of the people living here came from Mexico, and the area is now a centre for art and (3)____. I walked around for hours, looking at the colourful street (4)____ on the walls. It was quite modern and lively. Afterwards, I ate some delicious Mexican-Chinese noodles from a food (5)____. What a real (6)____ of cultures! In the evening I went to Chinatown, where there were so many good restaurants to (7)____ from. I (8)____ a small one that served its food on beautiful (9)____ plates. The food was wonderful. That is more than enough for one day, but I am already looking forward to (10)____.', 147, 2, '[{"q":"1","answer":"A","options":["trip","price","noise","rule"],"explanation":"camping trip 露营之旅。"},{"q":"2","answer":"B","options":["downhill","downtown","outside","afraid"],"explanation":"near downtown 靠近市中心。"},{"q":"3","answer":"C","options":["fear","fire","food","fog"],"explanation":"a centre for art and food 艺术与美食中心。"},{"q":"4","answer":"D","options":["exam","rule","price","art"],"explanation":"street art 街头艺术。"},{"q":"5","answer":"A","options":["truck","chair","table","shelf"],"explanation":"food truck 餐车。"},{"q":"6","answer":"B","options":["loss","mix","rest","noise"],"explanation":"a real mix of cultures 真正的文化融合。"},{"q":"7","answer":"C","options":["escape","sleep","choose","fall"],"explanation":"choose from 从中选择。"},{"q":"8","answer":"D","options":["lost","broke","dropped","selected"],"explanation":"selected a small one 挑了一家小餐馆。"},{"q":"9","answer":"A","options":["china","paper","glass","metal"],"explanation":"china plates 瓷盘。"},{"q":"10","answer":"B","options":["never","tomorrow","nothing","nobody"],"explanation":"looking forward to tomorrow 期待明天。"}]'::jsonb, 1);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required3', 'U3', 'Workers of the Gold Rush', 'In 1848, gold was found near the bay, and the news quickly (1)____ around the world. Soon hundreds of thousands of people came to (2)____ their fortune. Among them were many Chinese workers, who arrived during this busy (3)____. Life was hard, and to (4)____ a living they took any job they could find. Some opened small (5)____ in the area that later became Chinatown. Others helped to build the long (6)____ that joined the west of the country to the east. The work was tiring and the pay was (7)____, but they kept going year after year. When they left their home country, they (8)____ a little piece of home in their hearts. In (9)____, they built a new home in a faraway land. Their hard work became an important (10)____ of the country''s history.', 136, 2, '[{"q":"1","answer":"C","options":["fell","slept","spread","broke"],"explanation":"the news spread 消息传开。"},{"q":"2","answer":"D","options":["lose","drop","hide","seek"],"explanation":"seek their fortune 寻找致富之路。"},{"q":"3","answer":"A","options":["period","price","noise","rule"],"explanation":"this busy period 这段繁忙时期。"},{"q":"4","answer":"B","options":["throw","earn","waste","lose"],"explanation":"earn a living 谋生。"},{"q":"5","answer":"C","options":["seas","stars","shops","hills"],"explanation":"small shops 小店铺。"},{"q":"6","answer":"D","options":["song","river","garden","railway"],"explanation":"the long railway 那条长铁路。"},{"q":"7","answer":"A","options":["low","tall","wide","loud"],"explanation":"the pay was low 报酬很低。"},{"q":"8","answer":"B","options":["sold","carried","lost","broke"],"explanation":"carried a little piece of home 心里带着一点家乡。"},{"q":"9","answer":"C","options":["price","noise","time","fear"],"explanation":"in time 最终。"},{"q":"10","answer":"D","options":["price","noise","rest","part"],"explanation":"an important part of history 历史的重要部分。"}]'::jsonb, 2);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required3', 'U3', 'Learning to Make Fusion Noodles', 'Last summer I learned to cook a dish that (1)____ two cultures in one bowl. My uncle runs a small food truck, and he kindly agreed to (2)____ me. First he showed me how to (3)____ the right vegetables, all fresh and (4)____. Then he added a (5)____ sauce that made the dish hot and full of flavour. "The secret," he said, "is not being (6)____ to mix ideas from different places." His noodles bring together Mexican and Chinese (7)____, and people love them. While I was (8)____ him work, I understood that good food, like good culture, is often a happy (9)____ of many things. By the end of the day, I could make the dish on my own, and I felt very (10)____ of what I had learned.', 130, 2, '[{"q":"1","answer":"A","options":["mixes","breaks","loses","sells"],"explanation":"mixes two cultures 融合两种文化。"},{"q":"2","answer":"B","options":["forget","teach","lose","leave"],"explanation":"teach me 教我。"},{"q":"3","answer":"C","options":["throw","drop","select","hide"],"explanation":"select the right vegetables 挑选合适的蔬菜。"},{"q":"4","answer":"D","options":["angry","afraid","asleep","clean"],"explanation":"fresh and clean 新鲜又干净。"},{"q":"5","answer":"A","options":["spicy","quiet","empty","silent"],"explanation":"a spicy sauce 辛辣的酱汁。"},{"q":"6","answer":"B","options":["happy","afraid","glad","proud"],"explanation":"not being afraid to mix 不怕融合。"},{"q":"7","answer":"C","options":["weather","machine","cooking","garden"],"explanation":"Mexican and Chinese cooking 墨中两种烹饪。"},{"q":"8","answer":"D","options":["selling","losing","hiding","watching"],"explanation":"while I was watching him 当我看着他时。"},{"q":"9","answer":"A","options":["mix","loss","noise","fear"],"explanation":"a happy mix of many things 多种事物的愉快融合。"},{"q":"10","answer":"B","options":["sorry","proud","afraid","bored"],"explanation":"proud of what I had learned 为所学感到自豪。"}]'::jsonb, 3);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required3', 'U3', 'Justin''s Trip to the Villages', 'Justin was super (1)____ about his trip to Guizhou, a province known for its cultural (2)____. On the first day, he watched local people (3)____ an old instrument that has a history of over a thousand (4)____. He was surprised to learn that it is even (5)____ in the oldest collection of Chinese poetry. Justin wanted to buy some hand-made silver (6)____ as gifts. A villager told him the price would (7)____ on how much real silver each piece held. The next day, they planned to (8)____ a pretty village beside a clear river. There they hoped to see traditional (9)____ and old wooden houses. By the end of the trip, Justin felt that Chinese culture was far more (10)____ than he had ever imagined.', 125, 2, '[{"q":"1","answer":"C","options":["afraid","bored","excited","sorry"],"explanation":"super excited 超级兴奋。"},{"q":"2","answer":"D","options":["price","weather","noise","diversity"],"explanation":"cultural diversity 文化多样性。"},{"q":"3","answer":"A","options":["play","sell","lose","throw"],"explanation":"play an old instrument 演奏一件古老乐器。"},{"q":"4","answer":"B","options":["metres","years","seconds","prices"],"explanation":"over a thousand years 一千多年。"},{"q":"5","answer":"C","options":["lost","sold","mentioned","broken"],"explanation":"mentioned in the collection 在诗集中被提及。"},{"q":"6","answer":"D","options":["machines","gardens","rivers","accessories"],"explanation":"silver accessories 银饰品。"},{"q":"7","answer":"A","options":["depend","leave","sell","lose"],"explanation":"depend on 取决于。"},{"q":"8","answer":"B","options":["lose","visit","drop","throw"],"explanation":"visit a pretty village 参观一座美丽的村寨。"},{"q":"9","answer":"C","options":["prices","noises","dances","machines"],"explanation":"traditional dances 传统舞蹈。"},{"q":"10","answer":"D","options":["empty","boring","silent","diverse"],"explanation":"far more diverse 多样得多。"}]'::jsonb, 4);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required3', 'U3', 'A Souvenir Shop in Chinatown', 'My grandmother runs a small (1)____ shop in Chinatown, and I help her after school. The store offers all kinds of goods, from clothing to (2)____ medicine. Many tourists come in just to (3)____ around and enjoy the sights and smells of China. My grandmother always keeps the shelves (4)____ and tidy. "A neat shop," she says, "makes visitors feel (5)____." She knows the story behind every (6)____ on the shelves, and she loves to share it. Some customers want to (7)____ a gift for a friend far away. Others simply enjoy learning about Chinese culture (8)____ hand. The (9)____ here is mild all year round, so the street is always busy. Working in the shop has taught me that even a small place can hold a (10)____ history.', 129, 2, '[{"q":"1","answer":"A","options":["souvenir","machine","garden","river"],"explanation":"souvenir shop 纪念品店。"},{"q":"2","answer":"B","options":["loud","herbal","empty","afraid"],"explanation":"herbal medicine 草药。"},{"q":"3","answer":"C","options":["sleep","fall","look","lose"],"explanation":"look around 四处看看。"},{"q":"4","answer":"D","options":["angry","afraid","asleep","neat"],"explanation":"keeps the shelves neat 把货架收拾整齐。"},{"q":"5","answer":"A","options":["welcome","sorry","afraid","bored"],"explanation":"feel welcome 感到受欢迎。"},{"q":"6","answer":"B","options":["noise","item","price","rule"],"explanation":"every item on the shelves 货架上的每件商品。"},{"q":"7","answer":"C","options":["lose","throw","select","drop"],"explanation":"select a gift 挑选礼物。"},{"q":"8","answer":"D","options":["last","next","least","first"],"explanation":"first hand 亲身地。"},{"q":"9","answer":"A","options":["climate","price","noise","machine"],"explanation":"the climate is mild 气候温和。"},{"q":"10","answer":"B","options":["short","long","wide","loud"],"explanation":"a long history 悠久的历史。"}]'::jsonb, 5);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required3', 'U3', 'Welcome to Chinatown', 'The Chinatown here is the biggest in the country, and also the (1)____. It is a very popular place that (2)____ more visitors each year than even the famous bridge. The (3)____ is mild all year round, so it is always a good time to visit. Long ago, Chinese (4)____ settled in this area during the railroad period. What began as a place to live slowly turned into a (5)____ for Chinese culture. Most of the people here are still ethnic Chinese, and this lets visitors (6)____ a real taste of China. The old gate was built using (7)____ donated from China. The stores offer a wide range of souvenirs, goods, and (8)____. All kinds of Chinese herbal medicine can be (9)____ here too. But what many people treasure most is the food, with traditional dishes that (10)____ everyone''s taste.', 140, 2, '[{"q":"1","answer":"C","options":["loudest","coldest","oldest","saddest"],"explanation":"the oldest 最古老的。"},{"q":"2","answer":"D","options":["loses","breaks","sells","receives"],"explanation":"receives more visitors 接待更多游客。"},{"q":"3","answer":"A","options":["climate","noise","price","machine"],"explanation":"the climate is mild 气候温和。"},{"q":"4","answer":"B","options":["machines","immigrants","gardens","rivers"],"explanation":"Chinese immigrants 华人移民。"},{"q":"5","answer":"C","options":["loss","noise","centre","fear"],"explanation":"a centre for culture 文化中心。"},{"q":"6","answer":"D","options":["lose","throw","drop","experience"],"explanation":"experience a real taste 体验真正的味道。"},{"q":"7","answer":"A","options":["materials","machines","gardens","rivers"],"explanation":"built using materials 用材料建造。"},{"q":"8","answer":"B","options":["noise","clothing","weather","price"],"explanation":"souvenirs, goods, and clothing 纪念品、商品和服装。"},{"q":"9","answer":"C","options":["lost","sold","found","broken"],"explanation":"can be found 能被找到。"},{"q":"10","answer":"D","options":["lose","break","drop","suit"],"explanation":"dishes that suit everyone''s taste 适合各种口味的菜。"}]'::jsonb, 6);
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U3 听力·对话 The Origins of American Food', '必修三 U3 · dialogue', 3, 'Host: Welcome back. Today we ask: does America have any food of its own?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U3 听力·短文 The First People of California', '必修三 U3 · passage', 2, 'No one knows exactly when the first people arrived in what we now call California.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U3 听力·对话 Planning a Visit to Chinatown', '必修三 U3 · dialogue', 3, 'Mia: Are you free this afternoon? I''d love to show you Chinatown.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U3 听力·短文 An Ancient Instrument', '必修三 U3 · passage', 2, 'In many ethnic minority villages, people still play an old instrument called the lusheng.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U3 听力·对话 Different Tastes in Food', '必修三 U3 · dialogue', 3, 'Ann: There''s a potluck dinner this weekend. What dish will you bring?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U3 听力·短文 A City of Many Languages', '必修三 U3 · passage', 2, 'Some neighbourhoods are so diverse that almost half of the people were born in another country.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit) VALUES (10, 'Introduce a Place with a Diverse Culture(介绍一个文化多元的地方)', 'A Place of Diverse Cultures', '假设你是李华,一位外国笔友想了解一个文化多元的地方。请用英语写一篇约100词的介绍文,内容包括:① 这个地方在哪里、有怎样的历史;② 这里住着哪些不同的人/民族,有什么特色美食;③ 有哪些值得一看的名胜或活动,并说明为什么文化多元是它的魅力所在。注意:信息具体、条理清楚、有恰当的开头和结尾。', 'Suppose you are Li Hua. A foreign pen-friend wants to learn about a culturally diverse place. Write an introduction (about 100 words) including: 1) where the place is and a little of its history; 2) the different people or ethnic groups who live there and a special food; 3) some attractions or activities worth seeing, and why its diversity makes it special. Be specific, well-organised, with a clear beginning and conclusion.', '["位置与历史(… is located in … / has a long history of …)","人口与民族 + 特色美食(People here come from … / is home to … ethnic groups / famous for …)","名胜与活动(Famous sites include … / Visitors can …)","总结魅力(Its cultural diversity makes it a wonderful place to visit.)"]'::jsonb, 70, 100, 'Chinatown in San Francisco is one of the most diverse places I know. Located near downtown, it has a long history, for Chinese immigrants settled here during the gold rush and railroad period. Today most residents are still ethnic Chinese, and visitors can enjoy traditional food to suit every taste, from spicy dishes to herbal tea. Famous sites include the old Dragon Gate, built with materials donated from China, where people practise tai chi in the square. The climate is mild all year round, so it is always a good time to visit. Its rich mix of cultures makes Chinatown a truly special place.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["Chinatown is one of the most diverse places I know.","Chinese immigrants settled here during the gold rush and railroad period.","Visitors can enjoy traditional food to suit every taste.","Its rich mix of cultures makes Chinatown a truly special place."]'::jsonb, '[{"wrong":"It is located in near downtown.","correct":"It is located near downtown.","note":"be located near 已含''位于'',不再加 in。"},{"wrong":"The people here is from many countries.","correct":"The people here are from many countries.","note":"people 作复数,谓语用 are。"},{"wrong":"When in here, you can enjoy the food.","correct":"When here, you can enjoy the food.","note":"状语从句省略后用 When here,不加多余的 in。"}]'::jsonb, '【文化多元地方介绍结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content) VALUES (10, 'required3', 'U3', '{"title":"省略(Ellipsis)速查","intro":"省略就是为避免重复、让表达更简洁,而省去上下文中可以推知的成分。判断口诀:省什么都要能''还原'',还原后句子完整、意思不变。本单元三类:不定式后省动词、状语从句省''主语+be''、对话/并列句省重复成分。","table":{"headers":["类型","怎么省 / 例句"],"rows":[["不定式省略","保留 to,省后面动词:—Will you join? —I''d love to. / want to / didn''t mean to"],["状语从句省略","连词 + V-ing/V-ed/adj,省''主语+be'':When in Rome … / If necessary … / Though tired …"],["对话答语省略","只留新信息或助动词:—Where? —To the library. / Yes, I have. / Can''t wait!"],["并列句省略","省重复谓语,用 so/neither 或助动词:He can swim, and so can I. / I have, but she hasn''t."]]},"specialRules":[{"rule":"不定式后若动词为 be 或完成体 have,需保留 to be / to have","mark":"—Are you a member? —I''d like to be."},{"rule":"状语从句省略的前提:从句主语 = 主句主语(或为 it)且谓语含 be","mark":"When (you are) young vs ×When I young, you …"},{"rule":"so + 助动词 + 主语 = 前者肯定后者也如此;neither/nor + 助动词 + 主语 = 否定也如此","mark":"so do I / neither do I"},{"rule":"So it is(附和)≠ So is it(后者也如此),语序不同意思不同","mark":"—It''s cold. —So it is.(的确)"}],"why":["省略的本质是''上下文已给出信息,不必再说一遍''。能省的成分都能根据上文唯一还原;一旦还原不出或意思变了,就不能省。"],"gaokaoPoints":["状语从句的省略(when/while/if/though + 分词/形容词)是语法填空与短文改错高频考点;看清主句主语是否一致、动作主动(V-ing)还是被动(V-ed)。","不定式的省略(保留 to)、so/neither 倒装附和句,在完成句子与对话补全中常考。"],"examVsReal":[{"exam":"If (it is) necessary, call me.(书面省略,正式)","real":"Call me if you need to.","note":"考试爱考''连词+adj/分词''的省略;口语里常换成更直白的说法。"},{"exam":"—Will you come? —I''d love to.(标准省略)","real":"—Coming? —Love to!","note":"考试保留 to;真实口语连主语和 to 都可能再省。"}]}'::jsonb);
